prompt --application/shared_components/user_interface/templates/list/moment_launcher
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(104017078189311967)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TMomentLauncher #COMPONENT_CSS_CLASSES#" id="#LIST_ID#" data-weekend="" data-l-morning="This morning" data-l-afternoon="This afternoon" data-l-evening="This evening" data-l-night="Tonight" data-l-workhours="Working hours" data-l-weekday="Working day" data-l-weekend="Weekend" data-l-weekstart="Start of the week" data-l-weekclose="Last working day of the week" data-l-monthstart="Month start" data-l-monthend="Month-end" data-l-quarterstart="Quarter start" data-l-quarterend="Quarter-end" data-l-yearend="Year-end" data-l-lastday="Last day of the month" data-left-one="{n} working day left" data-left-other="{n} working days left" data-left-last="last working day" data-next="Next" data-announce="Suggested for right now:">',
'<div class="amc-TMomentLauncher-now" hidden>',
'<div class="amc-TMomentLauncher-nowHead"><span class="amc-TMomentLauncher-pulse" aria-hidden="true"></span><h3 class="amc-TMomentLauncher-heading">Right now</h3><span class="amc-TMomentLauncher-clock"></span></div>',
'<ul class="amc-TMomentLauncher-nowList"></ul>',
'</div>',
'<div class="amc-TMomentLauncher-restHead" hidden><h3 class="amc-TMomentLauncher-heading amc-TMomentLauncher-heading--rest">Everything else</h3><button type="button" class="amc-TMomentLauncher-toggle" aria-expanded="false" hidden><span class="amc-TMomentLauncher-toggleShow">Show all</span><span class="amc-TMomentLauncher-toggleHide">Show less</span><span class="amc-TMomentLauncher-toggleIcon fa fa-chevron-down" aria-hidden="true"></span></button></div>',
'<ul class="amc-TMomentLauncher-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'<p class="amc-TMomentLauncher-status" role="status" aria-live="polite"></p>',
'</div>'))
,p_list_template_current=>'<li class="amc-TMomentLauncher-item is-current" data-moments="#A01#"><a class="amc-TMomentLauncher-link" href="#LINK#" aria-current="page"><span class="amc-TMomentLauncher-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMomentLauncher-body"><span class="amc-TMomentLauncher-label">#TEXT#</span><span class="amc-TMomentLauncher-desc">#A02#</span></span><span class="amc-TMomentLauncher-badge">#A03#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TMomentLauncher-item" data-moments="#A01#"><a class="amc-TMomentLauncher-link" href="#LINK#"><span class="amc-TMomentLauncher-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMomentLauncher-body"><span class="amc-TMomentLauncher-label">#TEXT#</span><span class="amc-TMomentLauncher-desc">#A02#</span></span><span class="amc-TMomentLauncher-badge">#A03#</span></a></li>'
,p_list_template_name=>'AMC Moment Launcher'
,p_internal_name=>'AMC_TPL_MOMENT_LAUNCHER'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-moment-launcher.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-moment-launcher.css'
,p_a01_label=>'Moments'
,p_a02_label=>'Description'
,p_a03_label=>'Badge'
,p_list_template_comment=>'Launcher list template that follows the calendar. Attribute 1 holds the entry''s moments: space-separated alternatives, each made of one or more tokens joined with a plus sign that must all match, for example monthend quarterend or friday+afternoon. Tokens: morning (5 to 12 h), afternoon (12 to 17 h), evening (17 to 22 h), night, workhours (8 to 18 h on working days), weekday, weekend, weekstart and weekclose (first and last working day of the week), monday to sunday (or mon to sun), monthstart (first 3 working days), monthend (last 3 working days), quarterstart, quarterend (last 5 working days of March, June, September, December), yearend (last 10 working days of December), lastday, and day1 to day31 (day31 means the last day in shorter months). Unknown tokens never match. Working days skip the weekend of the page locale taken from Intl week info, for example Friday and Saturday for Arabic; set data-weekend on the wrapper in the template, for example friday saturday, to fix it. Public holidays are not known. Matching entries move into the Right now panel, most specific first (a date period outranks a weekday, which outranks a time of day), with a reason chip such as Month-end, 2 working days left; the last working day is highlighted. Other entries keep the developer''s order and show when they come up next. The time is the browser''s local time; the set is checked again every minute and when the tab becomes visible, but items never move while focus is inside the list, and changes are announced politely. Nothing is stored. Developers can test a moment in the browser console with amcTplMomentLauncher.at 2026-09-29T15:00 as a string argument and go back with null. Attribute 2 is a description, Attribute 3 a badge. Template options: Focus on now folds the other entries behind a Show all button, Hide next times, Spotlight fills the lifted entries with the primary color, Compact. Without JavaScript it is a plain list of links. Reduced motion stops the live pulse. English UI strings to translate in the template: Right now, Everything else, Show all, Show less, and the data-l-*, data-left-*, data-next and data-announce attributes on the wrapper; day and date names come from Intl in the page language.'
);
end;
/
